# -*- coding: utf-8 -*-
"""Привязка ответа по домену — хирургически, по якорям.

Целиком файлы заменить нельзя: соседняя сессия дописала в imap_watcher
_rfc_kandidaty, а в store — целый блок про копии. Ставим ровно три куска,
каждый якорь обязан встретиться один раз.

Катить: --katit
"""
import base64
import io
import json
import os
import py_compile
import sys
import time

Д = json.loads(base64.b64decode("").decode("utf-8"))
КАТИТЬ = "--katit" in sys.argv

W = r"C:\sender\sender\imap_watcher.py"
S = r"C:\sender\sender\store.py"

ЯКОРЬ_МЕТОД = "    def _process_event(self, ev: InboundEvent, mailbox_id: str) -> None:"
ЯКОРЬ_ФОЛБЭК = """        if recipient_id is None and orig_to:
            recipient_id = self._recipient_by_emails(orig_to)"""
ЯКОРЬ_СТОР = """    def iter_recipients(
        self, *, valid_status: Optional[str] = None, provider: Optional[str] = None,"""


def правка(путь, пары, метка):
    имя = os.path.basename(путь)
    т = io.open(путь, encoding="utf-8").read()
    if метка in т:
        print("%-18s правка уже стоит" % имя)
        return
    for як, новое, куда in пары:
        n = т.count(як)
        print("   %-18s якорь найден раз: %d" % (имя, n))
        if n != 1:
            raise SystemExit("якорь должен быть ровно один: %r" % як[:60])
        т = т.replace(як, (новое + як) if куда == "до" else (як + новое))
    if not КАТИТЬ:
        print("   сухой прогон, станет %d знаков" % len(т))
        return
    копия = "%s.bak-%d" % (путь, int(time.time()))
    io.open(копия, "w", encoding="utf-8", newline="").write(
        io.open(путь, encoding="utf-8").read())
    with io.open(путь, "w", encoding="utf-8", newline="") as f:
        f.write(т)
        f.flush()
        os.fsync(f.fileno())
    py_compile.compile(путь, doraise=True)
    print("   поставлен %s (.bak %s)" % (имя, os.path.basename(копия)))


print("=== imap_watcher ===")
правка(W, [(ЯКОРЬ_МЕТОД, Д["metod"], "до"),
           (ЯКОРЬ_ФОЛБЭК, "\n" + Д["folbek"].rstrip("\n"), "после")],
       "_recipient_by_domain")
print("=== store ===")
правка(S, [(ЯКОРЬ_СТОР, Д["stor"], "до")], "recipients_by_domain")
if not КАТИТЬ:
    print("\nсухой прогон. Катить: --katit")
